const D = { energy:.6, scale:1, density:.5, speed:1, hue:28, flip:.6, hatch:.55, x:.5, y:.5, style:'engrave', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);

if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;

// ---- rhombille: the dual of the trihexagonal Laves tiling -----------------
// Split every hexagon into three 60/120 rhombi meeting at its centre. Because
// the hexagon's side equals its circumradius, (C,v0,v1,v2) has four equal sides
// -- a true rhombus. Shade the three as the top/left/right faces of a cube and
// the plane reads as tumbling blocks. Cycling the three tones by one flips the
// cube inside out: that is the Necker reversal this piece sweeps across as a wave.
const VX=[], VY=[];
for (let i=0;i<6;i++){ const a = Math.PI/6 + i*Math.PI/3; VX[i]=Math.cos(a); VY[i]=Math.sin(a); }
const T0X = VX[0]+VX[1], T0Y = VY[0]+VY[1];
const T1X = VX[1]+VX[2], T1Y = VY[1]+VY[2];

const ax = cl(P.x,.2,.8)*width, ay = cl(P.y,.2,.8)*height;
const corner = Math.max(Math.hypot(ax,ay), Math.hypot(width-ax,ay), Math.hypot(ax,height-ay), Math.hypot(width-ax,height-ay));
const R = Math.max(u*.115*cl(P.scale,.55,2.2), corner/9.2);
const rot = .19*Math.sin(K.t*.0389*sp) + .08*Math.sin(K.t*.0971*sp+1.7);
S.gx = (S.gx||0) + dt*sp*(.085 + .06*Math.sin(K.t*.043))*R;
S.gy = (S.gy||0) + dt*sp*(.050 + .06*Math.cos(K.t*.057+2.2))*R;

const ca = Math.abs(Math.cos(rot)), sa = Math.abs(Math.sin(rot));
const dxm = Math.max(ax, width-ax), dym = Math.max(ay, height-ay);
const hx = dxm*ca + dym*sa + R*2, hy = dxm*sa + dym*ca + R*2;
const step = 1.732*R;
const na = Math.ceil(hx/(step*.5)) + 2, nb = Math.ceil(hy/(step*.5)) + 2;

// ---- styles ---------------------------------------------------------------
const glow = (sty==='xray');
function grd(){
  if (sty==='riso')     return [44, 9, 93];
  if (sty==='quilt')    return [28, 22, 16];
  if (glow)             return [(H+192)%360, 56, 5];
  if (sty==='concrete') return [(H+180)%360, 4, 54];
  return [(H+6)%360, 14, 88];                      // engrave: bone plate
}
// three cube faces: 0 top, 1 left, 2 right
function faceCol(f, lam, wv, jit){
  const base = [1.0, .58, .78][f];
  const v = (base*(.45 + .62*lam))*(.6+.5*en) + wv*.35 + .05*jit;
  if (sty==='riso')     return [ [352,205,46][f], cl(58 - 12*f,10,88), cl(52 + 48*v, 12, 100) ];
  if (sty==='quilt')    return [ (H + f*22 + 8)%360, cl(56 - 12*f, 8, 82), cl(20 + 62*v, 5, 96) ];
  if (glow)             return [ (H + 130 + f*54)%360, 44, cl(14 + 86*v, 2, 100) ];
  if (sty==='concrete') return [ (H+180)%360, cl(3 + f,0,10), cl(26 + 58*v, 4, 92) ];
  return [ (H + 2 + f*9)%360, cl(24 - 5*f, 4, 44), cl(30 + 58*v, 4, 98) ];
}

const gc = grd(); noStroke(); background(gc[0], gc[1], gc[2]);
const lang = K.t*.081*sp + .55*Math.sin(K.t*.0293+1.2);
const lgx = Math.cos(lang), lgy = Math.sin(lang);
const fdir = K.t*.041*sp + .7;
const fnx = Math.cos(fdir), fny = Math.sin(fdir);
const fwv = cl(P.flip,0,1);
const hw = cl(P.hatch,0,1);

push(); translate(ax, ay); rotate(rot);
strokeJoin(ROUND);
const jw = (u/900)*(.55 + 1.9*en);
let drawn = 0;

for (let a=-na;a<=na;a++){
  for (let b=-nb;b<=nb;b++){
    const cx = (a*T0X + b*T1X)*R - S.gx, cy = (a*T0Y + b*T1Y)*R - S.gy;
    if (Math.abs(cx) > hx || Math.abs(cy) > hy) continue;
    const dl = Math.hypot(cx,cy) || 1;
    const lam = cl(.5 + .5*((cx/dl)*lgx + (cy/dl)*lgy), 0, 1);
    // the reversal front: behind it every cube has turned inside out
    const ph = (cx*fnx + cy*fny)/(R*4.2) - K.t*.62*sp;
    const rev = fwv * (.5 + .5*Math.sin(ph));
    const hard = rev > .5 ? 1 : 0;
    const wv = Math.pow(Math.abs(Math.sin(ph)), 12) * fwv * (.55+.5*bass) * lift;   // the seam glints as it passes
    const jit = fr(a*17.7 + b*31.3);
    for (let f=0;f<3;f++){
      const i0 = f*2;
      const q0x = cx, q0y = cy;
      const q1x = cx + VX[i0]*R,          q1y = cy + VY[i0]*R;
      const q2x = cx + VX[(i0+1)%6]*R,    q2y = cy + VY[(i0+1)%6]*R;
      const q3x = cx + VX[(i0+2)%6]*R,    q3y = cy + VY[(i0+2)%6]*R;
      const fi = (f + hard) % 3;                 // <- the Necker flip: cycle the tones
      const c = faceCol(fi, lam, wv, jit);
      if (glow) {
        blendMode(ADD);
        noStroke(); fill(c[0], c[1], c[2], cl(6 + 15*lam + 20*wv, 2, 42));
        quad(q0x,q0y,q1x,q1y,q2x,q2y,q3x,q3y);
        blendMode(BLEND);
        noFill(); stroke(c[0], c[1], cl(c[2]*(.5+.6*lam+.5*wv),0,100), cl(26 + 56*lam, 8, 92));
        strokeWeight(jw*(.7+.9*wv)); quad(q0x,q0y,q1x,q1y,q2x,q2y,q3x,q3y);
      } else {
        noStroke(); fill(c[0], c[1], c[2], 100);
        quad(q0x,q0y,q1x,q1y,q2x,q2y,q3x,q3y);
        // engraved hatching runs along each face's OWN axis -> three rulings
        if (hw > .05 && R > 16) {
          stroke(c[0], cl(c[1]+16,0,100), cl(c[2]*.56,0,100), 14 + 40*hw);
          strokeWeight(jw*.4);
          const nh = 2 + Math.round(hw*3);
          for (let k2=1;k2<=nh;k2++){
            const t2 = k2/(nh+1);
            line(q0x + (q1x-q0x)*t2, q0y + (q1y-q0y)*t2, q3x + (q2x-q3x)*t2, q3y + (q2y-q3y)*t2);
          }
        }
        noFill(); stroke(gc[0], cl(gc[1]*1.15,0,100), cl(gc[2]*(.42+.5*(1-en)),0,100), 84);
        strokeWeight(jw); quad(q0x,q0y,q1x,q1y,q2x,q2y,q3x,q3y);
      }
    }
    drawn++;
    if (drawn > 190) break;
  }
  if (drawn > 190) break;
}
pop();

// ---- moving chiaroscuro ---------------------------------------------------
const lw2 = 180, lh2 = cl(Math.round(180*height/Math.max(1,width)), 60, 340);
if (!S.lg || S.lgk !== lw2+'x'+lh2) { S.lg = createGraphics(lw2, lh2); S.lg.colorMode(HSB,360,100,100,100); S.lgk = lw2+'x'+lh2; }
const L = S.lg;
L.push(); L.noStroke(); L.blendMode(BLEND);
L.background(0, 0, 100 - (16 + 28*en));
L.blendMode(ADD);
const plx = (.5 + .30*Math.cos(lang))*lw2, ply = (.5 + .26*Math.sin(lang*1.19+1.6))*lh2;
for (let i=0;i<9;i++){
  const q=i/8, rr=Math.max(lw2,lh2)*(1.26-q*.98);
  L.fill(0,0,100, (6 + 7.5*en + 5*bass)*(.26+.74*q*q));
  L.ellipse(plx, ply, rr*2, rr*2);
}
L.blendMode(BLEND); L.pop();
blendMode(MULTIPLY); noStroke(); image(L, 0, 0, width, height); blendMode(BLEND);

// ---- cached grain ---------------------------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw=420, th=280, t=createGraphics(tw,th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2200;i++){
    const rr=.4+fr(i*5.71)*1.8;
    t.fill(32, 8, 100-fr(i*6.37)*42, 50);
    t.ellipse(fr(i*2.91)*tw, fr(i*3.41+2.9)*th, rr, rr);
  }
  S.tex = t; S.texk = tk;
}
blendMode(MULTIPLY); noStroke(); image(S.tex, 0, 0, width, height); blendMode(BLEND);

if (P.alpha < 100) { noStroke(); fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0;
